import{_ as s,o as t,c as o,ag as n}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Reusing a Response","description":"","frontmatter":{},"headers":[],"relativePath":"guide/datahub-reusing-responses.md","filePath":"guide/datahub-reusing-responses.md"}'),a={name:"guide/datahub-reusing-responses.md"};function r(i,e,d,h,l,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="reusing-a-response" tabindex="-1">Reusing a Response <a class="header-anchor" href="#reusing-a-response" aria-label="Permalink to &quot;Reusing a Response&quot;">​</a></h1><p>Some APIs return everything in one call. A warehouse queue, for example, may hold shipment headers, package lines and reason codes in a single list. Inner reads and child endpoints often need more of that same data for each record: &quot;the load row for this shipment&quot;, &quot;the packages on this order&quot;, &quot;the reason code for this line&quot;.</p><p>If each of those reads sends its own request, the endpoint downloads the whole response again for <strong>every</strong> record. A run with 1,000 records can make thousands of identical calls.</p><p><strong>Use the response from</strong> lets a read take the response an earlier read already fetched in the same run, instead of sending its own request.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Use it when an inner read or a child endpoint&#39;s read:</p><ul><li>Sends <strong>the same request for every record</strong>: its URL and body don&#39;t change from record to record, <strong>and</strong></li><li>Narrows the rows down with its <strong>Data Selector</strong>, for example <code>Collection[?(@.Load_Nbr == &#39;{CD:Load}&#39;)]</code>.</li></ul><p>The configuration validator warns about reads like this: <em>&quot;This read sends the same request for every record…&quot;</em>. When the warning names an endpoint, that endpoint&#39;s read already fetches the data.</p><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><ol><li><p>Open the inner read, or the child endpoint&#39;s read, on the <strong>Get Changes</strong> action.</p></li><li><p>In <strong>Use the response from</strong>, choose the endpoint whose read already returns the data. The list shows:</p><ul><li><strong>This endpoint</strong> (inner reads only)</li><li><strong>The endpoints it runs under</strong> (its parent, grandparent, and so on)</li></ul><p>Each option shows the endpoint name, the read&#39;s title and its request path, e.g. <code>HyTek - 0615 › Read · GET RequestWMSMessages</code>. Once you choose one, its full request shows below the picker.</p></li><li><p>Keep your <strong>Data Selector</strong>; it&#39;s required. Placeholders such as <code>{CD:Load}</code> or <code>{FK:SalesOrderId}</code> are still filled in for each record. The selector now picks rows from the reused response. <code>{SYS:ParentId}</code> and <code>{SYS:PrimaryId}</code> aren&#39;t filled in inside a selector, so match the record with <code>{PK:…}</code>, <code>{FK:…}</code> or <code>{CD:…}</code> instead.</p></li></ol><p>When a source is chosen, the read sends no request. The URL, body, paging and instruction settings are hidden and cleared, because they no longer apply. The action card shows a <i class="far fa-recycle"></i> badge with the source&#39;s name.</p><h3 id="what-stays-the-same" tabindex="-1">What stays the same <a class="header-anchor" href="#what-stays-the-same" aria-label="Permalink to &quot;What stays the same&quot;">​</a></h3><p>Mapping, filters, aggregation and keys work exactly as before. The read sees the same rows it would have fetched itself. The difference is that every lookup in a run sees <strong>one</strong> snapshot of the data, even if the source system changes partway through the run.</p><h2 id="trim-response-values" tabindex="-1">Trimming padded values <a class="header-anchor" href="#trim-response-values" aria-label="Permalink to &quot;Trimming padded values {#trim-response-values}&quot;">​</a></h2><p>Some systems pad values with spaces (<code>&#39;114605977 &#39;</code>). Instead of adding a trim transform to every map, switch on <strong>Trim Response Values</strong> on the read that sends the request. It&#39;s available on any read action of a JSON, XML or SQL endpoint, and on the top-level read of a file endpoint, and it also applies to webhook payloads. Each read decides for its own response, so a future-publish read has its own switch. Every text value in the response is trimmed once, as it arrives:</p><ul><li>Every map on that endpoint sees trimmed values.</li><li>Reads that reuse the response see them too, marked with a <i class="far fa-scissors"></i> <strong>Trimmed by …</strong> chip.</li><li>Selectors can compare with <code>==</code>: <code>@.Load_Nbr == &#39;{CD:Load}&#39;</code> matches once the padding is gone.</li></ul><p><strong>Test Request</strong> on a read with the switch on shows the trimmed response, as the run would see it. To see the raw values, turn the switch off on the read and test again.</p><p>For a single padded field, use the <strong>Trim</strong> transform instead (both sides, start only, or end only).</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Valid sources.</strong> A read can reuse the response of its own endpoint (inner reads only) or of an endpoint it runs under. It can&#39;t use a child&#39;s response; children run later.</li><li><strong>Polling publishers only.</strong> Reuse works on the publisher&#39;s <strong>Get Changes</strong> read and its inner reads, for JSON and XML endpoints that call an API. Both endpoints must use the same protocol. Webhook publishers and future-publish endpoints start from a single record, without the source&#39;s response, so the option isn&#39;t offered there.</li><li><strong>Not on connector-specific data services.</strong> Endpoints that use a connector&#39;s own data service can neither reuse a response nor be a source.</li><li><strong>Sources must send their own request.</strong> The source read must send its own request and must not <strong>Load Children Together</strong>. While other reads reuse an endpoint&#39;s response, its read shows how many depend on it and keeps those options locked.</li><li><strong>No Test Request.</strong> A read that reuses a response sends no request, so it has no Test Request. Test the source read instead.</li><li><strong>No silent fallback.</strong> If the source hasn&#39;t been read in the run, the read reports an error. It never falls back to sending its own request.</li></ul>',20)])])}const g=s(a,[["render",r]]);export{p as __pageData,g as default};
